'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security headers (helmet sets X-Content-Type-Options, CSP, HSTS, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing — strict size limit to prevent large-payload DoS attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — applied globally; tighten per-route as needed
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,     // Return RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Request logging (lightweight; swap for winston/pino in production)
// ---------------------------------------------------------------------------
app.use((req, _res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// List users
// TODO: Replace static data with DB queries and add authentication middleware
app.get('/users', (_req, res) => {
  // Input validation example: safe query-param handling
  // (extend this with a library like zod or joi for complex schemas)
  const rawLimit = req.query.limit;
  const limit = rawLimit !== undefined ? parseInt(rawLimit, 10) : undefined;

  if (limit !== undefined && (Number.isNaN(limit) || limit < 1 || limit > 100)) {
    return res.status(400).json({ error: '`limit` must be an integer between 1 and 100.' });
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const result = limit !== undefined ? users.slice(0, limit) : users;
  res.json(result);
});

// ---------------------------------------------------------------------------
// 5. 404 handler — catches requests to undefined routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — MUST have 4 parameters for Express to treat it
//    as an error handler. Avoids leaking stack traces to clients.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  const isDev = process.env.NODE_ENV === 'development';

  console.error(`[ERROR] ${err.message}`, isDev ? err.stack : '');

  // Never expose raw error details in production
  const status = typeof err.status === 'number' ? err.status : 500;
  res.status(status).json({
    error: isDev ? err.message : 'An unexpected error occurred.',
  });
});

// ---------------------------------------------------------------------------
// 7. Configurable port via environment variable
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
});

module.exports = app;

