'use strict';

const express = require('express');
const helmet  = require('helmet');        // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app  = express();
const PORT = Number(process.env.PORT) || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (X-Content-Type-Options, X-Frame-Options, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing — enforce a size limit to prevent payload-flooding attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — applies to all routes
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation example: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Unexpected query parameter(s): ${invalidParams.join(', ')}`,
      });
    }

    // Validate and sanitise pagination params
    const page  = parsePositiveInt(req.query.page,  1);
    const limit = parsePositiveInt(req.query.limit, 10);

    if (!page || !limit || limit > 100) {
      return res.status(400).json({
        error: '`page` and `limit` must be positive integers; `limit` must be ≤ 100.',
      });
    }

    // Placeholder data (replace with real DB call)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    res.json({ page, limit, total: users.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 4. 404 handler — must come after all valid routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 5. Global error handler — 4-argument signature is required by Express
//    IMPORTANT: never expose stack traces or internal details to the client
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the full error server-side for debugging
  console.error('[ERROR]', err);

  // Return a safe, generic message to the client
  const statusCode = Number.isInteger(err.status) ? err.status : 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.info(`[INFO] Server running on port ${PORT}`);
  });
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses a value as a positive integer.
 * @param {*} value - The raw input to parse.
 * @param {number} defaultValue - Fallback when value is undefined/null.
 * @returns {number|null} The parsed integer, or null if invalid.
 */
function parsePositiveInt(value, defaultValue) {
  if (value === undefined || value === null) return defaultValue;
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
}

module.exports = app;

