'use strict';

const express = require('express');
const helmet = require('helmet'); // Sets secure HTTP headers

const app = express();

// ---------------------------------------------------------------------------
// Security Middleware
// ---------------------------------------------------------------------------

// Set secure HTTP headers (X-Content-Type-Options, X-Frame-Options, etc.)
app.use(helmet());

// Parse JSON bodies with a hard size cap to prevent large-payload DoS attacks
app.use(express.json({ limit: '10kb' }));

// ---------------------------------------------------------------------------
// Helper: centralise error responses so internal details are never leaked
// ---------------------------------------------------------------------------
function sendError(res, status, message) {
  res.status(status).json({ error: message });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters
    const ALLOWED_PARAMS = new Set(['limit', 'offset']);
    const receivedParams = Object.keys(req.query);
    const unknownParams = receivedParams.filter((p) => !ALLOWED_PARAMS.has(p));

    if (unknownParams.length > 0) {
      return sendError(
        res,
        400,
        `Unknown query parameter(s): ${unknownParams.join(', ')}`
      );
    }

    // Input validation: 'limit' must be a safe positive integer (max 100)
    let limit = 100;
    if (req.query.limit !== undefined) {
      limit = parseInt(req.query.limit, 10);
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
        return sendError(res, 400, "'limit' must be an integer between 1 and 100.");
      }
    }

    // Input validation: 'offset' must be a safe non-negative integer
    let offset = 0;
    if (req.query.offset !== undefined) {
      offset = parseInt(req.query.offset, 10);
      if (!Number.isInteger(offset) || offset < 0) {
        return sendError(res, 400, "'offset' must be a non-negative integer.");
      }
    }

    // --- Replace with a real database call in production ---
    const ALL_USERS = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const page = ALL_USERS.slice(offset, offset + limit);
    res.json(page);
  } catch (err) {
    // Pass unexpected errors to the global error handler
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 404 Handler — must come AFTER all valid routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  sendError(res, 404, 'Resource not found.');
});

// ---------------------------------------------------------------------------
// Global Error Handler — must have exactly 4 arguments so Express recognises it
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging …
  console.error('[ERROR]', err);

  // … but never expose stack traces or internal messages to the client
  sendError(res, 500, 'An unexpected error occurred. Please try again later.');
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

// Read port from environment so the app is portable across environments
const PORT = process.env.PORT || 3000;

// Only start listening when this module is run directly (not during tests)
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

