'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// Security middleware
// ---------------------------------------------------------------------------

// Set secure HTTP response headers (removes X-Powered-By, adds CSP, etc.)
app.use(helmet());

// Parse JSON bodies with a strict size limit to prevent large-payload attacks
app.use(express.json({ limit: '10kb' }));

// Apply a global rate limit: max 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Unexpected query parameter(s): ${invalidParams.join(', ')}`,
      });
    }

    // Validate and sanitise pagination parameters
    const page = parseInt(req.query.page, 10);
    const limit = parseInt(req.query.limit, 10);

    if (req.query.page !== undefined && (isNaN(page) || page < 1)) {
      return res.status(400).json({ error: "'page' must be a positive integer." });
    }

    if (req.query.limit !== undefined && (isNaN(limit) || limit < 1 || limit > 100)) {
      return res.status(400).json({ error: "'limit' must be an integer between 1 and 100." });
    }

    // Static data — replace with a real DB call in production
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 404 handler — must be registered after all valid routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// Global error handler — must have exactly 4 arguments for Express to use it
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  // Never leak stack traces or internal details to the client
  const statusCode = typeof err.status === 'number' ? err.status : 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'An internal server error occurred.'
      : err.message;

  res.status(statusCode).json({ error: message });
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

// Only start listening when this file is run directly, not when imported by tests
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

