const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  // Intentionally minimal — do NOT expose version, hostname, or env name
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation example: optional ?limit= query parameter
    const MAX_LIMIT = 100;
    const rawLimit = req.query.limit;

    if (rawLimit !== undefined) {
      const limit = parseInt(rawLimit, 10);

      if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
        return res.status(400).json({
          error: `'limit' must be an integer between 1 and ${MAX_LIMIT}.`,
        });
      }
    }

    // In a real app this data would come from a DB call wrapped in try/catch
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const limit = rawLimit ? parseInt(rawLimit, 10) : users.length;
    res.json(users.slice(0, limit));
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 404 handler — must be defined after all valid routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// Global error handler — must have exactly 4 arguments so Express recognises it
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally but never send stack traces to the client
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  const statusCode = Number.isInteger(err.status) ? err.status : 500;
  res.status(statusCode).json({
    error:
      process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred.'
        : err.message, // Show message only in non-production environments
  });
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

// Only start the server when this file is run directly (not when imported in tests)
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

