const usersValidation = [
  query('page')
    .optional()
    .isInt({ min: 1 }).withMessage('page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100')
    .toInt(),
];

app.get('/users', usersValidation, (req, res) => {
  // 7. Reject requests that fail validation — never process bad input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In production: replace with a real DB query using parameterised queries
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // 8. Basic pagination to prevent large data dumps
  const page  = req.query.page  || 1;
  const limit = req.query.limit || 10;
  const start = (page - 1) * limit;
  const paginated = users.slice(start, start + limit);

  res.json({
    page,
    limit,
    total: users.length,
    data: paginated,
  });
});

// ─── 404 Handler ──────────────────────────────────────────────────────────────
// 9. Catch requests to undefined routes before they hit the error handler
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ─── Global Error Handler ─────────────────────────────────────────────────────
// 10. Must have exactly 4 parameters so Express recognises it as an error handler
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Never leak stack traces or internal details to the client
  console.error(`[ERROR] ${err.message}`, { stack: err.stack });

  const status = err.status || err.statusCode || 500;
  res.status(status).json({
    error: status === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// ─── Start Server ─────────────────────────────────────────────────────────────
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

