/**
 * app.js — Express application with security best practices applied.
 *
 * Key improvements over the original:
 *  - helmet:        Sets secure HTTP response headers.
 *  - express-rate-limit: Protects against brute-force / DoS.
 *  - Body parsing with size limits: Prevents oversized payload attacks.
 *  - Input validation: Query/param sanitisation on every route.
 *  - 404 handler:   Returns JSON instead of leaking HTML/framework info.
 *  - Global error handler: Catches all thrown errors; never exposes stack
 *                   traces in production.
 *  - Environment-driven config: Port resolved from process.env.
 *  - Request logging: Morgan in 'combined' format for audit trails.
 */

'use strict';

const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan  = require('morgan');

const app  = express();
const PORT = parseInt(process.env.PORT, 10) || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (X-Content-Type-Options, X-Frame-Options, CSP, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Request logging — use 'combined' for production-grade audit trails
// ---------------------------------------------------------------------------
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ---------------------------------------------------------------------------
// 3. Body parsing with strict size limits to prevent payload-flooding attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. Global rate limiter — tighten windowMs / max for sensitive routes
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,     // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health — no sensitive data, but still behind rate limiter + helmet
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — demonstrates query-parameter input validation
app.get('/users', (req, res, next) => {
  try {
    // Example: optional ?limit= query param — validate before use
    const { limit } = req.query;

    if (limit !== undefined) {
      const parsed = Number(limit);
      if (!Number.isInteger(parsed) || parsed < 1 || parsed > 100) {
        // 400 Bad Request with a safe, descriptive message
        return res.status(400).json({
          error: 'Invalid "limit" parameter. Must be an integer between 1 and 100.',
        });
      }
    }

    // In a real app this data comes from a DB; never interpolate raw query
    // params directly into SQL/NoSQL queries — use parameterised queries.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    const result = limit ? users.slice(0, Number(limit)) : users;
    res.json(result);
  } catch (err) {
    // Forward unexpected errors to the global error handler
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 5. 404 handler — must be defined AFTER all valid routes
//    Returns JSON (not Express's default HTML) so no framework info leaks.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — four-argument signature is required by Express.
//    Never sends stack traces to the client in production.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Always log the full error server-side for debugging / audit purposes
  console.error(`[ERROR] ${req.method} ${req.originalUrl} —`, err);

  const statusCode = typeof err.status === 'number' ? err.status : 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: isProduction
      ? 'An unexpected error occurred. Please try again later.'
      : err.message, // Expose message in non-production for easier debugging
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap — only start listening when this module is the entry point,
// not when it is imported by tests.
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
  });
}

module.exports = app;

