const express = require('express');

// ------------------------------------------------------------
// Security middleware — install via:
//   npm install helmet express-rate-limit
// ------------------------------------------------------------
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ── 1. Security headers (X-Content-Type-Options, X-Frame-Options, etc.) ──────
app.use(helmet());

// ── 2. Body parsing with a strict size limit to prevent payload-based DoS ────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ── 3. Rate limiting — 100 requests per 15 minutes per IP ────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── 4. Port from environment, with a safe fallback ───────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Input validation example: reject unexpected query parameters
  const allowedParams = new Set(['page', 'limit']);
  const receivedParams = Object.keys(req.query);
  const unknownParams = receivedParams.filter((p) => !allowedParams.has(p));

  if (unknownParams.length > 0) {
    return res.status(400).json({
      error: 'Invalid query parameters.',
      unknown: unknownParams,
    });
  }

  // Validate and sanitize pagination parameters
  const page = parseInt(req.query.page, 10);
  const limit = parseInt(req.query.limit, 10);

  if (req.query.page !== undefined && (isNaN(page) || page < 1)) {
    return res.status(400).json({ error: "'page' must be a positive integer." });
  }

  if (req.query.limit !== undefined && (isNaN(limit) || limit < 1 || limit > 100)) {
    return res.status(400).json({ error: "'limit' must be an integer between 1 and 100." });
  }

  // NOTE: In a real application, query a database here rather than
  // returning hardcoded data. Never expose sensitive fields (passwords,
  // tokens, internal IDs) in API responses.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// ── 5. Catch-all 404 handler ─────────────────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ── 6. Global error handler (must have 4 arguments for Express to use it) ────
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for diagnostics, never send it to the client
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Return a generic message so internal details are not leaked
  const statusCode = typeof err.status === 'number' ? err.status : 500;
  res.status(statusCode).json({ error: 'An unexpected error occurred.' });
});

// ── Server startup ────────────────────────────────────────────────────────────
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

