'use strict';

const express = require('express');
const helmet = require('helmet');           // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet() sets a suite of protective HTTP headers automatically,
//    including X-Content-Type-Options, X-Frame-Options, and more.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. BODY PARSING — with a strict size limit to prevent large-payload DoS.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING
//    Applies to all routes. Adjust `max` and `windowMs` to suit your needs.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Max 100 requests per IP per window
  standardHeaders: true,     // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. ROUTES
// ---------------------------------------------------------------------------

// Health check — intentionally minimal; never expose internal details here.
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list
app.get('/users', (_req, res) => {
  // TODO: Replace with a parameterised database query.
  // Never interpolate user input directly into queries.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ---------------------------------------------------------------------------
// 5. 404 HANDLER
//    Catches any request that didn't match a defined route.
//    Returns a generic message — never reveal available routes.
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ---------------------------------------------------------------------------
// 6. GLOBAL ERROR HANDLER
//    Must have exactly 4 arguments so Express recognises it as an error handler.
//    - Logs the full error server-side for diagnostics.
//    - Returns only a generic message to the client to avoid leaking internals
//      (stack traces, file paths, dependency versions, etc.).
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the real error internally (swap for your structured logger in production)
  console.error('[ERROR]', err);

  // Respond with a safe, generic message
  res.status(err.status || 500).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// 7. SERVER STARTUP
//    Read the port from the environment; fall back to 3000 for local dev only.
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;

// Only start listening when this file is run directly,
// not when it is imported by tests.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
